&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;TIMING:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We have three start dates per year. The&amp;nbsp;start&amp;nbsp;class you will be considered for depends on when&amp;nbsp;you&amp;nbsp;apply.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;WHAT TO EXPECT: &amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;1&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Your online application,&amp;nbsp;essays&amp;nbsp;and resume will serve as an introduction to who you are as a candidate.&amp;nbsp;Once you complete the online application, we will begin reviewing your profile. &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Selected candidates will then receive an email invitation to&amp;nbsp;participate&amp;nbsp;in a case study, allowing you to&amp;nbsp;showcase&amp;nbsp;your experiences and&amp;nbsp;demonstrate&amp;nbsp;your business acumen.  &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;3&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Following submission and review of your case study, the next step would be an online assessment and virtual one on one interviews with various members of the Academy team, if selected.  &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;ABOUT POINT72&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Point72 is a leading global alternative investment firm led by Steven A. Cohen.&amp;nbsp;Building on&amp;nbsp;more than 30 years of investing experience, Point72 seeks to deliver superior returns for its investors through fundamental and systematic investing strategies across asset classes and geographies. We aim to attract and&amp;nbsp;retain&amp;nbsp;the industry’s brightest talent by cultivating an investor-led culture and committing to our people’s long-term growth.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re&amp;nbsp;a firm that thrives on ideas, and&amp;nbsp;we’ve&amp;nbsp;found that the Point72 Academy has provided us with diverse viewpoints and perspectives. We&amp;nbsp;can&amp;nbsp;offer support in&amp;nbsp;Academy Associates’&amp;nbsp;growth and development as analysts and portfolio managers.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;For more information, visit&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;http://www.point72.com/working-here&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;www.Point72.com/working-here&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;There is no set application deadline for this position. Candidates are considered as they apply, until the program is at&amp;nbsp;capacity. We strongly encourage you to apply and fulfill all requirements as soon as you feel ready to begin the hiring process. Please&amp;nbsp;note,&amp;nbsp;you may only&amp;nbsp;submit&amp;nbsp;one application to the Academy program globally, so please be sure to apply to the region you are most interested in.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Don&#39;t&amp;nbsp;miss this opportunity to kickstart your career in the world of investing with Point72 Academy. &amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The US annual base salary for this role is $125,000 (USD)&amp;nbsp;which&amp;nbsp;does not include discretionary bonus compensation or our comprehensive benefits package. Actual compensation offered to the successful candidate may vary from posted hiring based upon geographic location, work experience, education, and/or skill level, among other things.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Pursuant to&amp;nbsp;the San Francisco Fair Chance Ordinance, we will consider for employment qualified applicants with arrest and conviction records. &lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Please note that any use of&amp;nbsp;GenAI&amp;nbsp;is&amp;nbsp;strictly prohibited&amp;nbsp;when completing this application.&lt;/span&gt;&lt;/em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;

Tower Research Capital::gh_towerresearch.description:
&lt;p&gt;Tower Research Capital is a leading quantitative trading firm founded in 1998. Tower has built its business on a high-performance platform and independent trading teams. We have a 25+ year track record of innovation and a reputation for discovering unique market opportunities.&lt;br&gt;&lt;br&gt;Tower is home to some of the world’s best systematic trading and engineering talent. We empower portfolio managers to build their teams and strategies independently while providing the economies of scale that come from a large, global organization.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Engineers thrive at Tower while developing electronic trading infrastructure at a world class level. Our engineers solve challenging problems in the realms of low-latency programming, FPGA technology, hardware acceleration and machine learning. Our ongoing investment in top engineering talent and technology ensures our platform remains unmatched in terms of functionality, scalability and performance.&lt;/p&gt;
&lt;p&gt;At Tower, every employee plays a role in our success. Our Business Support teams are essential to building and maintaining the platform that powers everything we do — combining market access, data, compute, and research infrastructure with risk management, compliance, and a full suite of business services. Our Business Support teams enable our trading and engineering teams to perform at their best.&lt;/p&gt;
&lt;p&gt;At Tower, employees will find a stimulating, results-oriented environment where highly intelligent and motivated colleagues inspire each other to reach their greatest potential.&lt;/p&gt;
&lt;h3&gt;Responsibilities:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Designing, implementing, and deploying mid- to high-frequency trading algorithms&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Exploring trading ideas by analyzing market data and market microstructure for patterns&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Creating tools to analyze data for patterns&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Contributing to libraries of analytical computations to support market data analysis and trading&lt;/li&gt;
&lt;li&gt;Developing, augmenting, and calibrating exchange simulators&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Qualifications:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;PhD or Postdoctoral research focusing on mathematics, statistics, computer science, physics, machine learning, or related fields&lt;/li&gt;
&lt;li&gt;Proficient in an object-oriented programming language (C++ and Python preferred)&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A working knowledge of Linux/Unix&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Strong problem-solving abilities&amp;nbsp;&lt;/li&gt;
&lt;li&gt;A passion for new technologies and ideas&lt;/li&gt;
&lt;li&gt;The ability to manage multiple tasks in a fast-paced environment&lt;/li&gt;
&lt;li&gt;Strong communication skills&lt;/li&gt;
&lt;li&gt;Interest in financial markets&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Preferred Qualifications (not required):&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Past industry experience&lt;/li&gt;
&lt;li&gt;Experience as a Teaching Assistant and/or participation in relevant Olympiads&lt;/li&gt;
&lt;li&gt;Familiarity with machine learning, data analysis, market research and data modeling&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Benefits:&lt;/h3&gt;
&lt;p&gt;Tower’s headquarters are in the historic Equitable Building, right in the heart of NYC’s Financial District and our impact is global, with over a dozen offices around the world.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;At Tower, we believe work should be both challenging and enjoyable. That is why we foster a culture where smart, driven people thrive – without the egos. Our open concept workplace, casual dress code, and well-stocked kitchens reflect the value we place on a friendly, collaborative environment where everyone is respected, and great ideas win.&lt;/p&gt;
&lt;h3&gt;Our benefits include:&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Competitive compensation package&lt;/li&gt;
&lt;li&gt;Free breakfast, lunch, and snacks daily&lt;/li&gt;
&lt;li&gt;Exciting networking and social events&lt;/li&gt;
&lt;li&gt;Opportunities to learn from senior management across the firm&lt;/li&gt;
&lt;li&gt;Mentors from your alma mater and other top institutions&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;At Tower, you’ll find a collaborative and welcoming culture, a diverse team and a workplace that values both performance and enjoyment. No unnecessary hierarchy. No ego. Just great people doing great work – together.&lt;/p&gt;
&lt;p&gt;Tower Research Capital is an equal opportunity employer.&lt;/p&gt;

TransMarket Group::gh_transmarketgroup_5.description:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;Who We Are&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Founded in 1980 as Aardvark Financial, TransMarket Group (TMG) is a privately held global markets proprietary trading firm in Chicago. We use next-generation technology to capture opportunities around the world and manage risk in financial markets. Our mission is to bless others through the services we provide and through the generous stewardship of the wealth we create.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;TMG is a well-established and profitable business as a respected member of the global financial system for over 40 years, but also is like a startup because the potential of our group is at least one order of magnitude greater than what we are currently producing. We have an entrepreneurial culture and collaboratively develop our business with patience and discipline; we work hard, learn constantly, and relentlessly improve our expertise.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Description&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;padding-left: 40px;&quot;&gt;TMG is seeking an Experienced Mid-Frequency Quantitative Researcher / Trader with a track record of success to lead an entrepreneurial initiative in this area at the firm.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;div class=&quot;styles--2BkR3&quot; data-ui=&quot;job-description&quot;&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Research and develop predictive features and signals for mid and high frequency trading&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Design and maintain robust frameworks for signal evaluation, including backtesting and performance diagnostics.&lt;/li&gt;
&lt;li&gt;Continuously monitor and refine features and signals to adapt to evolving market dynamics, ensuring feature and signal robustness across regimes and conditions.&lt;/li&gt;
&lt;li&gt;Monitor and analyze the performance of signals post-production, identifying degradation and opportunities for refinement.&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;styles--2kg4_&quot; data-ui=&quot;job-requirements&quot;&gt;
&lt;h4&gt;Requirements&lt;/h4&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;Breadth and depth in mathematical background&lt;/li&gt;
&lt;li&gt;Passion and experience in feature engineering, signal generation, and building robust predictive models&lt;/li&gt;
&lt;li&gt;3+ years experience as a quantitative researcher with specific experience in the Interest Rate space&lt;/li&gt;
&lt;li&gt;Bachelor&#39;s, Master&#39;s, or Doctorate in technical field&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Benefits&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We offer one of the most generous profit sharing programs in the industry because we believe our employees should be able to take part in our rapid growth and success. We are proud to offer more world-class &lt;/span&gt;&lt;a href=&quot;https://www.transmarketgroup.com/benefits&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;benefits&lt;/span&gt;&lt;/a&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; for our full-time employees and their families.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;&lt;em&gt;TransMarket Group is an equal opportunity employer. All qualified applicants will receive consideration for employment without regard to race, color, gender, sexual orientation, gender identity or expression, religion, national origin, marital status, age, disability, veteran status, genetic information, or any other protected status.&lt;/em&gt;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

Jump Trading::gh_jumptrading_8050796.description:
&lt;p&gt;Jump Trading is committed to world class research. We empower exceptional talents in Mathematics, Physics, and Computer Science to seek scientific boundaries, push through them, and apply cutting edge research to global financial markets. Our culture is unique. Constant innovation requires fearlessness, creativity, intellectual honesty, and a relentless competitive streak. We believe in winning together and unlocking unique individual talent by incentivising collaboration and mutual respect. At Jump, research outcomes drive more than superior risk adjusted returns. We design, develop, and deploy technologies that change our world, fund start-ups across industries, and partner with leading global research organisations and universities to solve problems.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the Role:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We build predictive models from big data and develop algorithms to automatically execute trades in dozens of financial exchanges around the world.&lt;/p&gt;
&lt;p&gt;At Jump you will have the opportunity to contribute in a blend of three roles – quant researcher / data scientist, trader, and software developer – based on your incoming skills and background, interest and curiosity, and the new skills and industry knowledge that you will learn at Jump.&lt;/p&gt;
&lt;p&gt;You will start by completing a training program focused on enhancing your knowledge of trading, programming, and quant research. The training consists of in-house courses and trading simulation developed and delivered by experienced quant researchers, traders, and developers. We have experts from around the firm who will teach you advanced skills in a variety of areas such as Trading / Market Mechanics, Statistics, R, Python, C++, Machine Learning, and our research process.&lt;/p&gt;
&lt;p&gt;You will later be coached to successfully apply those skills to build predictive models, leveraging one of the largest supercomputers in the world, and devise automated trading strategies to test in the markets against world-class competition.&lt;/p&gt;
&lt;p&gt;May include other duties as assigned or needed.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Who should apply?&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are seeking the sharpest analytical minds from top undergraduate and graduate programs. Ideal candidates have an uncommon drive to learn and improve, an entrepreneurial spirit, and strong skills in programming and/or quantitative analysis (statistics, data mining, mathematics, machine learning, etc.).&lt;/p&gt;
&lt;p&gt;No prior knowledge of finance or trading is necessary. We’ll give you the training that you’ll need. Reliable and predictable availability required.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Although we strongly value training in Computer Science and Mathematics, we are excited to meet people with exceptional achievements in any technical discipline. Recent hires include students from fields such as Electrical Engineering, Statistics, Physics, Neuroscience, Materials Science, Operations Research, and more.&lt;/p&gt;
&lt;p&gt;If you have outstanding skills in math and programming and you are curious about the challenge of improving research with daily feedback from competitive markets, we hope you’ll apply.&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;Benefits include:&lt;/p&gt;
&lt;ul class=&quot;p-rich_text_list p-rich_text_list__bullet&quot; data-stringify-type=&quot;unordered-list&quot; data-indent=&quot;0&quot; data-border=&quot;0&quot;&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Private Medical, Vision and Dental Insurance&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Travel Medical Insurance&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Group Pension Scheme&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Group Life Assurance and Income Protection Schemes&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Paid Parental Leave&lt;/li&gt;
&lt;li data-stringify-indent=&quot;0&quot; data-stringify-border=&quot;0&quot;&gt;Parking and Commuter Benefits&lt;/li&gt;
&lt;/ul&gt;

Jump Trading::gh_jumptrading_8027939.description:
